#!/usr/bin/env bash
set -euo pipefail
infer_system() { case "$(uname -m)" in x86_64) echo x86_64-linux;; aarch64|arm64) echo aarch64-linux;; *) echo "error: unsupported machine architecture: $(uname -m)" >&2; exit 1;; esac; }
find_container_tarball() { local result_link="$1" candidate; if [[ ! -e "${result_link}" ]]; then echo "error: nix build out-link not found: ${result_link}" >&2; exit 1; fi; if [[ -f "${result_link}" ]]; then echo "${result_link}"; return 0; fi; for candidate in "${result_link}/image.tar" "${result_link}/image.tar.gz" "${result_link}/image.tgz"; do if [[ -f "${candidate}" ]]; then echo "${candidate}"; return 0; fi; done; candidate="$(find -L "${result_link}" -maxdepth 2 -type f \( -name '*.tar' -o -name '*.tar.gz' -o -name '*.tgz' \) | head -n 1 || true)"; if [[ -n "${candidate}" ]]; then echo "${candidate}"; return 0; fi; echo "error: could not locate container tarball under ${result_link}" >&2; exit 1; }
SYSTEM="${1:-$(infer_system)}"; REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"; OUT_LINK="${REPO_ROOT}/result-container"; ARTIFACT_DIR="${REPO_ROOT}/images"; ARTIFACT_PATH="${ARTIFACT_DIR}/determinate-nix-${SYSTEM}.tar.gz"; cd "${REPO_ROOT}"; echo "Building container for system=${SYSTEM}..."; nix build ".#packages.${SYSTEM}.container" --out-link "${OUT_LINK}" --print-build-logs; TARBALL_SRC="$(find_container_tarball "${OUT_LINK}")"; mkdir -p "${ARTIFACT_DIR}"; if [[ "${TARBALL_SRC}" == *.tar.gz || "${TARBALL_SRC}" == *.tgz ]]; then cp -f "${TARBALL_SRC}" "${ARTIFACT_PATH}"; else gzip -c "${TARBALL_SRC}" > "${ARTIFACT_PATH}"; fi; echo "Container image staged at ${ARTIFACT_PATH}"; ls -lh "${ARTIFACT_PATH}"
